class ExpensiveLookupCache
  def initialize
    @cache = {}
  end

  def fetch(key)
    return @cache[key] if @cache.key?(key)
    @cache[key] = ExpensiveLookup.call(key)
  end

  def warm(keys)
    keys.each { |key| Thread.new { fetch(key) } }
  end
end

cache = ExpensiveLookupCache.new
cache.warm(["us", "uk", "us", "de", "us"])
